rectsrc='''def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    fg = next(v for v in colors if v != bg)
    pref = [[0] * (w + 1) for _ in range(h + 1)]
    for r in range(h):
        for c in range(w):
            pref[r + 1][c + 1] = (grid[r][c] == bg) + pref[r][c + 1] + pref[r + 1][c] - pref[r][c]
    def area(r0, c0, r1, c1):
        return pref[r1][c1] - pref[r0][c1] - pref[r1][c0] + pref[r0][c0]
    out = [row[:] for row in grid]
    for top in range(-1, h):
        for bottom in range(top + 2, h + 1):
            r0, r1 = top + 1, bottom
            for left in range(-1, w):
                c0 = left + 1
                for right in range(left + 2, w + 1):
                    c1 = right
                    if area(r0, c0, r1, c1) != (r1 - r0) * (c1 - c0):
                        continue
                    if top >= 0 and any(grid[top][c] != fg for c in range(c0, c1)):
                        continue
                    if bottom < h and any(grid[bottom][c] != fg for c in range(c0, c1)):
                        continue
                    if left >= 0 and any(grid[r][left] != fg for r in range(r0, r1)):
                        continue
                    if right < w and any(grid[r][right] != fg for r in range(r0, r1)):
                        continue
                    for r in range(r0, r1):
                        for c in range(c0, c1):
                            out[r][c] = 4
    return out
'''
